from pathlib import Path
import hashlib,importlib.util,json,sys
import pandas as pd
from pytest import MonkeyPatch
root=Path(".")
label=sys.argv[1]
source=root/label
sys.path.insert(0,str(source))
spec=importlib.util.spec_from_file_location("demand_proof_fixture",root/"after/tests/test_gov_exposure.py")
fx=importlib.util.module_from_spec(spec);spec.loader.exec_module(fx)
from scripts import build_demand as bd
from engine import demand_chain as dc,demand_alerts,gov_exposure as ge
from lib import config
def digest(value):
    return hashlib.sha256(json.dumps(value,sort_keys=True,ensure_ascii=False,allow_nan=False,separators=(",",":")).encode()).hexdigest()
out={"label":label,"fixtures":{}}
for case,edits in fx._PIPELINE_CASES.items():
    with MonkeyPatch.context() as mp:
        result=fx._native_component_pipeline(root/("fixtures-v2-"+label)/case,mp,edits)
        cells,texts=fx._burden_cells(result["html"])
        out["fixtures"][case]={"signals":result["signals"],"reads":result["reads"],"burdens":result["burdens"],
            "texts":texts,"cell_attrs":[x[0] for x in cells],"html_sha256":hashlib.sha256(result["html"].encode()).hexdigest(),
            "signals_sha256":digest(result["signals"]),"reads_sha256":digest(result["reads"])}
frame=pd.read_parquet(source/"data/edgar/statements.parquet")
signals,reads,burdens=bd._collect(source)
assert signals and reads and burdens
for chain in dc.CHAINS:
    direct=ge.spender_capex_burden(frame,chain["key"])
    if direct: assert burdens.get(chain["key"])==direct
with MonkeyPatch.context() as mp:
    alert_calls=[];page_writes=[]
    mp.setattr(demand_alerts,"rebuild",lambda data,**kw:alert_calls.append(data) or [])
    def write_page(path,html):
        target=root/(label+"-current-demand.html");target.write_text(html);page_writes.append(target);return target
    mp.setattr(bd,"write_page",write_page)
    html=bd.build(root=source)
    assert len(page_writes)==1 and page_writes[0].read_text()==html and alert_calls==[reads]
current_rows={}
for chain,items in burdens.items():
    for ticker,burden in items.items():
        if burden is not None:
            _,texts=fx._burden_cells(html,ticker)
            current_rows[chain+"|"+ticker]={"burden":burden,"texts":texts}
out["current"]={"statement_rows":len(frame),"tickers":int(frame["ticker"].nunique()),
    "signals":signals,"reads":reads,"burdens":burdens,"payer_rows":current_rows,
    "signals_sha256":digest(signals),"reads_sha256":digest(reads),
    "html_sha256":hashlib.sha256(html.encode()).hexdigest()}
out["historical"]={}
for cutoff in sorted(int(x) for x in frame["fy"].dropna().unique()):
    past=frame[frame["fy"]<=cutoff]
    for chain in dc.CHAINS:
        for ticker,burden in ge.spender_capex_burden(past,chain["key"]).items():
            if burden is not None and burden["fy_latest"]==cutoff:
                out["historical"][chain["key"]+"|"+ticker+"|"+str(cutoff)]=burden
target=root/(label+"-audit.json")
target.write_text(json.dumps(out,sort_keys=True,ensure_ascii=False,allow_nan=False,indent=2)+"\n")
print(json.dumps({"label":label,"fixtures":len(out["fixtures"]),"statement_rows":len(frame),
"tickers":out["current"]["tickers"],"signals":len(signals),"reads":len(reads),
"payer_rows":len(current_rows),"historical_observations":len(out["historical"]),
"audit_sha256":hashlib.sha256(target.read_bytes()).hexdigest(),"audit_bytes":target.stat().st_size}),flush=True)

