from pathlib import Path
import hashlib,json
root=Path(".")
a=json.loads((root/"before-audit.json").read_text());b=json.loads((root/"after-audit.json").read_text())
fields={"fcf_latest_bn","fcf_trend","capex_ocf_trend","net_debt_delta_bn","fcf_trap"}
def changes(x,y):
    assert x.keys()==y.keys()
    return {k:{"before":x[k],"after":y[k]} for k in x if x[k]!=y[k]}
result={"current":{},"historical":{},"fixtures":{},"preserved":{}}
for key in ("signals","reads"):
    assert a["current"][key]==b["current"][key],key
    result["preserved"][key+"_count"]=len(a["current"][key])
    result["preserved"][key+"_sha256"]=b["current"][key+"_sha256"]
assert a["historical"].keys()==b["historical"].keys()
for key,x in a["historical"].items():
    y=b["historical"][key];delta=changes(x,y)
    assert set(delta)<=fields,(key,delta)
    assert all(v["after"] is None for v in delta.values()),(key,delta)
    if delta:result["historical"][key]=delta
for key,x in a["current"]["payer_rows"].items():
    y=b["current"]["payer_rows"][key];delta=changes(x["burden"],y["burden"])
    assert set(delta)<=fields
    if delta or x["texts"]!=y["texts"]:
        result["current"][key]={"changes":delta,"before":x,"after":y}
for case,x in a["fixtures"].items():
    y=b["fixtures"][case]
    assert x["signals"]==y["signals"] and x["reads"]==y["reads"],case
    for chain,items in x["burdens"].items():
        for ticker,payer in items.items():
            if ticker!="MSFT":assert payer==y["burdens"][chain][ticker],(case,chain,ticker)
    result["fixtures"][case]={"changes":changes(x["burdens"]["ai_datacenter"]["MSFT"],y["burdens"]["ai_datacenter"]["MSFT"]),
       "before":x["burdens"]["ai_datacenter"]["MSFT"],"after":y["burdens"]["ai_datacenter"]["MSFT"],
       "texts_before":x["texts"],"texts_after":y["texts"]}
result["summary"]={"statement_rows":b["current"]["statement_rows"],"tickers":b["current"]["tickers"],
"current_payers":len(b["current"]["payer_rows"]),"current_changed_payers":len(result["current"]),
"historical_observations":len(b["historical"]),"historical_changed_observations":len(result["historical"]),
"new_or_remeasured_numeric_values":0,"fixtures":len(result["fixtures"]),"all_fixture_signals_and_reads_identical":True}
result["audit_files"]=[{"name":label+"-audit.json","bytes":(root/(label+"-audit.json")).stat().st_size,"sha256":hashlib.sha256((root/(label+"-audit.json")).read_bytes()).hexdigest()} for label in ("before","after")]
(root/"comparison.json").write_text(json.dumps(result,sort_keys=True,ensure_ascii=False,allow_nan=False,indent=2)+"\n")
print(json.dumps({"summary":result["summary"],"preserved":result["preserved"],"current_changes":{k:v["changes"] for k,v in result["current"].items()},"historical_changes":result["historical"]},ensure_ascii=False),flush=True)
